14	// Generate produces one OpenAPI 3.1.0 JSON document per input proto file.
15	// Files without HTTP-bound services are skipped (no output file is emitted).
16	func Generate(reg *descriptor.Registry, files []*descriptor.File) ([]*pluginpb.CodeGeneratorResponse_File, error) {
17		var out []*pluginpb.CodeGeneratorResponse_File
18		for _, file := range files {
19			doc, ok := generateFile(reg, file)
20			if !ok {
21				// No HTTP annotations found, skip file.
22				continue
23			}
24			body, err := json.MarshalIndent(doc, "", "  ")
25			if err != nil {
26				return nil, fmt.Errorf("marshal %s: %w", file.GetName(), err)
27			}
28			base := strings.TrimSuffix(file.GetName(), path.Ext(file.GetName()))
29			out = append(out, &pluginpb.CodeGeneratorResponse_File{
30				Name:    proto.String(base + ".openapi.json"),
31				Content: proto.String(string(body)),
32			})
33		}
34		return out, nil
35	}
36	
37	// generateFile builds a Document for a single proto file. The boolean return
38	// is false when the file has no HTTP-bound operations to emit.
39	func generateFile(reg *descriptor.Registry, file *descriptor.File) (*Document, bool) {
40		name := file.GetName()
41		title := strings.TrimSuffix(path.Base(name), path.Ext(name))
42		doc := NewDocument(title, "1.0.0")
43		b := newSchemaBuilder(reg, doc)
44	
45		seenTags := make(map[string]bool)
46	
47		for _, svc := range file.Services {
48			tag := svc.GetName()
49			if !seenTags[tag] {
50				seenTags[tag] = true
51				doc.Tags = append(doc.Tags, &Tag{
52					Name:        tag,
53					Description: serviceComments(svc),
54				})
55			}
56	
57			for _, method := range svc.Methods {
58				for i, binding := range method.Bindings {
59					urlPath, pathParams := convertPathTemplate(binding.PathTmpl.Template)
60					op := buildOperation(b, svc, method, binding, i, pathParams)
61	
62					item, ok := doc.Paths.Get(urlPath)
63					if !ok {
64						item = &PathItem{}
65						doc.Paths.Set(urlPath, item)
66					}
67					item.SetOperation(binding.HTTPMethod, op)
68				}
69			}
70		}
71	
72		if doc.Paths.Len() == 0 {
73			return nil, false
74		}
75		if doc.Components.Empty() {
76			doc.Components = nil
77		}
78		return doc, true
79	}
