2	
3	import (
4		"slices"
5	
6		"github.com/grpc-ecosystem/grpc-gateway/v2/internal/descriptor"
7		"google.golang.org/genproto/googleapis/api/annotations"
8		"google.golang.org/grpc/grpclog"
9		"google.golang.org/protobuf/proto"
10		"google.golang.org/protobuf/types/descriptorpb"
11	)
12	
13	// schemaBuilder owns the in-progress component schema set for one document.
14	// Construction is intentionally lazy: schemas are only added when something
15	// references them, transitively from RPC request/response types. We never
16	// emit unreferenced messages.
17	type schemaBuilder struct {
18		reg *descriptor.Registry
19		doc *Document
20	}
21	
22	func newSchemaBuilder(reg *descriptor.Registry, doc *Document) *schemaBuilder {
23		return &schemaBuilder{
24			reg: reg,
25			doc: doc,
26		}
27	}
28	
29	// fieldSchema returns the schema (or $ref) describing the given proto field's
30	// type. For repeated fields it produces an array; for map entries it produces
31	// an object with additionalProperties; for messages and enums it produces a
32	// $ref into components and ensures the referenced schema is generated.
33	func (b *schemaBuilder) fieldSchema(field *descriptor.Field) *SchemaOrRef {
34		if field.GetLabel() != descriptorpb.FieldDescriptorProto_LABEL_REPEATED {
35			return b.scalarOrRef(field)
36		}
37		// Map fields are repeated synthetic messages with map_entry=true. Resolve
38		// the message once: a hit on map_entry takes the map path, a hit on a
39		// regular message hands the resolved descriptor to scalarOrRef so it does
40		// not have to look it up again, and a miss emits an open-object array
41		// directly (avoiding a redundant lookup in scalarOrRef).
42		if field.GetType() == descriptorpb.FieldDescriptorProto_TYPE_MESSAGE {
43			msg, err := b.reg.LookupMsg("", field.GetTypeName())
44			if err != nil {
45				grpclog.Infof("protoc-gen-openapiv3: cannot resolve message %q for repeated field %q: %v; emitting open object array",
46					field.GetTypeName(), field.GetName(), err)
47				return &SchemaOrRef{
48					Value: &Schema{
49						Type:  SchemaType{"array"},
50						Items: &SchemaOrRef{Value: &Schema{Type: SchemaType{"object"}}},
51					},
52				}
53			}
54			if msg.GetOptions().GetMapEntry() {
55				return b.mapSchema(msg)
56			}
57			return &SchemaOrRef{
58				Value: &Schema{
59					Type:  SchemaType{"array"},
60					Items: b.messageRef(msg),
61				},
62			}
63		}
64		return &SchemaOrRef{
65			Value: &Schema{
66				Type:  SchemaType{"array"},
67				Items: b.scalarOrRef(field),
68			},
69		}
70	}
71	
72	// messageRef returns a $ref to the given message's component schema, ensuring
73	// the component is generated. Well-known types are inlined instead.
74	func (b *schemaBuilder) messageRef(msg *descriptor.Message) *SchemaOrRef {
75		if wkt := wellKnownTypeSchema(msg.FQMN()); wkt != nil {
76			return &SchemaOrRef{Value: wkt}
77		}
78		b.ensureMessageSchema(msg)
79		return NewSchemaRef(schemaName(msg.FQMN()))
80	}
81	
82	// mapSchema returns the additionalProperties schema for a proto map field.
83	// Map entries are messages with two fields:
84	// key (1) and value (2); the value field's type drives additionalProperties.
85	func (b *schemaBuilder) mapSchema(msg *descriptor.Message) *SchemaOrRef {
86		var valueField *descriptor.Field
87		for _, f := range msg.Fields {
88			if f.GetNumber() == 2 {
89				valueField = f
90				break
91			}
92		}
93		if valueField == nil {
94			// Should not happen per the proto spec, but emit an open object
95			// rather than nil which would produce invalid OpenAPI.
96			return &SchemaOrRef{Value: &Schema{Type: SchemaType{"object"}}}
97		}
98		return &SchemaOrRef{
99			Value: &Schema{
100				Type: SchemaType{"object"},
101				AdditionalProperties: &AdditionalProperties{
102					Schema: b.scalarOrRef(valueField),
103				},
104			},
105		}
106	}
107	
108	// scalarOrRef produces the schema for a non-repeated field type. Message and
109	// enum types resolve to $refs into components; everything else is an inline
110	// scalar schema.
111	func (b *schemaBuilder) scalarOrRef(field *descriptor.Field) *SchemaOrRef {
112		switch field.GetType() {
113		case descriptorpb.FieldDescriptorProto_TYPE_STRING:
114			return &SchemaOrRef{Value: &Schema{Type: SchemaType{"string"}}}
115		case descriptorpb.FieldDescriptorProto_TYPE_INT32,
116			descriptorpb.FieldDescriptorProto_TYPE_SINT32,
117			descriptorpb.FieldDescriptorProto_TYPE_SFIXED32:
118			return &SchemaOrRef{Value: &Schema{Type: SchemaType{"integer"}, Format: "int32"}}
119		case descriptorpb.FieldDescriptorProto_TYPE_INT64,
120			descriptorpb.FieldDescriptorProto_TYPE_SINT64,
121			descriptorpb.FieldDescriptorProto_TYPE_SFIXED64:
122			// 64-bit ints are JSON strings per protojson.
123			return &SchemaOrRef{Value: &Schema{Type: SchemaType{"string"}, Format: "int64"}}
124		case descriptorpb.FieldDescriptorProto_TYPE_UINT32,
125			descriptorpb.FieldDescriptorProto_TYPE_FIXED32:
126			// OpenAPI has no "uint32" format; int64 is the narrowest that
127			// covers the full uint32 range.
128			return &SchemaOrRef{Value: &Schema{Type: SchemaType{"integer"}, Format: "int64"}}
129		case descriptorpb.FieldDescriptorProto_TYPE_UINT64,
130			descriptorpb.FieldDescriptorProto_TYPE_FIXED64:
131			return &SchemaOrRef{Value: &Schema{Type: SchemaType{"string"}, Format: "uint64"}}
132		case descriptorpb.FieldDescriptorProto_TYPE_FLOAT:
133			return &SchemaOrRef{Value: &Schema{Type: SchemaType{"number"}, Format: "float"}}
134		case descriptorpb.FieldDescriptorProto_TYPE_DOUBLE:
135			return &SchemaOrRef{Value: &Schema{Type: SchemaType{"number"}, Format: "double"}}
136		case descriptorpb.FieldDescriptorProto_TYPE_BOOL:
137			return &SchemaOrRef{Value: &Schema{Type: SchemaType{"boolean"}}}
138		case descriptorpb.FieldDescriptorProto_TYPE_BYTES:
139			return &SchemaOrRef{Value: &Schema{Type: SchemaType{"string"}, Format: "byte"}}
140		case descriptorpb.FieldDescriptorProto_TYPE_MESSAGE:
141			// Well-known types are inlined; everything else is referenced.
142			if wkt := wellKnownTypeSchema(field.GetTypeName()); wkt != nil {
143				return &SchemaOrRef{Value: wkt}
144			}
145			msg, err := b.reg.LookupMsg("", field.GetTypeName())
146			if err != nil {
147				grpclog.Infof("protoc-gen-openapiv3: cannot resolve message %q for field %q: %v; emitting open object",
148					field.GetTypeName(), field.GetName(), err)
149				return &SchemaOrRef{Value: &Schema{Type: SchemaType{"object"}}}
150			}
151			b.ensureMessageSchema(msg)
152			return NewSchemaRef(schemaName(msg.FQMN()))
153		case descriptorpb.FieldDescriptorProto_TYPE_ENUM:
154			enum, err := b.reg.LookupEnum("", field.GetTypeName())
155			if err != nil {
156				grpclog.Infof("protoc-gen-openapiv3: cannot resolve enum %q for field %q: %v; emitting plain string",
157					field.GetTypeName(), field.GetName(), err)
158				return &SchemaOrRef{Value: &Schema{Type: SchemaType{"string"}}}
159			}
160			b.ensureEnumSchema(enum)
161			return NewSchemaRef(schemaName(enum.FQEN()))
162		default:
163			// Fall back to a string value on unhandled field types
164			return &SchemaOrRef{Value: &Schema{Type: SchemaType{"string"}}}
165		}
166	}
167	
168	// ensureMessageSchema generates a component schema for the given message if
169	// it has not already been emitted. Map-entry messages are skipped.
170	func (b *schemaBuilder) ensureMessageSchema(msg *descriptor.Message) {
171		if msg.GetOptions().GetMapEntry() {
172			// Map entries are handled separately
173			return
174		}
175		name := schemaName(msg.FQMN())
176		if _, exists := b.doc.Components.Schemas[name]; exists {
177			// Message already in schema, skip
178			return
179		}
180	
181		// Reserve the slot up front so cycles terminate: when a nested field
182		// recurses into a message we're already building, the exists check
183		// above short-circuits instead of looping.
184		schema := &Schema{
185			Type:       SchemaType{"object"},
186			Deprecated: messageDeprecated(msg),
187		}
