1	// Command protoc-gen-openapiv3 implements an OpenAPI 3.1.0 generator for
2	// proto files annotated with google.api.http rules.
3	//
4	// Status: alpha. The emitted JSON shape is not yet stable — encodings for
5	// oneofs, wrapper types, enums, and path-template expansion may change
6	// between minor releases while the mapping rules settle in response to
7	// real-world feedback. For a production-stable OpenAPI pipeline today,
8	// use protoc-gen-openapiv2.
9	package main
10	
11	import (
12		"fmt"
13		"log"
14		"os"
15	
16		"github.com/grpc-ecosystem/grpc-gateway/v2/internal/codegenerator"
17		"github.com/grpc-ecosystem/grpc-gateway/v2/internal/descriptor"
18		"github.com/grpc-ecosystem/grpc-gateway/v2/protoc-gen-openapiv3/internal/genopenapi"
19		"google.golang.org/grpc/grpclog"
20		"google.golang.org/protobuf/proto"
21		"google.golang.org/protobuf/types/pluginpb"
22	)
23	
24	func main() {
25		// Write log output to standard error to prevent clobbering standard out.
26		// Drop the date/time prefix the standard logger adds by default — buf
27		// surfaces these messages interactively, so a timestamp adds noise
28		// without context.
29		log.SetOutput(os.Stderr)
30		log.SetPrefix("protoc-gen-openapiv3: ")
31		log.SetFlags(0)
32	
33		if err := run(); err != nil {
34			emitError(err)
35			os.Exit(1)
36		}
37	}
38	
39	func run() error {
40		req, err := codegenerator.ParseRequest(os.Stdin)
41		if err != nil {
42			return err
43		}
44	
45		reg := descriptor.NewRegistry()
46		if err := reg.Load(req); err != nil {
47			return err
48		}
49	
50		var targets []*descriptor.File
51		for _, name := range req.FileToGenerate {
52			f, err := reg.LookupFile(name)
53			if err != nil {
54				return err
55			}
56			targets = append(targets, f)
57		}
58	
59		out, err := genopenapi.Generate(reg, targets)
60		if err != nil {
61			return err
62		}
63	
64		emitFiles(out)
65		return nil
66	}
67	
68	func emitFiles(files []*pluginpb.CodeGeneratorResponse_File) {
69		resp := &pluginpb.CodeGeneratorResponse{File: files}
70		codegenerator.SetSupportedFeaturesOnCodeGeneratorResponse(resp)
71		emitResp(resp)
72	}
73	
74	func emitError(err error) {
75		// Echo to stderr in addition to the proto response
76		grpclog.Infoln(err)
77		emitResp(&pluginpb.CodeGeneratorResponse{Error: proto.String(err.Error())})
78	}
79	
80	func emitResp(resp *pluginpb.CodeGeneratorResponse) {
81		buf, err := proto.Marshal(resp)
82		if err != nil {
83			fmt.Fprintln(os.Stderr, err)
84			os.Exit(1)
85		}
86		if _, err := os.Stdout.Write(buf); err != nil {
87			fmt.Fprintln(os.Stderr, err)
88			os.Exit(1)
89		}
90	}
